//! Typed access to the members of a JSON object, following the protocol's
//! rules: `null` counts as absent, integers have no fraction or exponent, and
//! a wrong type or range is `InvalidParameterValue`.

use crate::error::{Code, Error, Result};
use serde_json::{Map, Value};
use std::ops::RangeInclusive;

pub struct Params<'a>(&'a Map<String, Value>);

impl<'a> Params<'a> {
    pub fn new(members: &'a Map<String, Value>) -> Self {
        Params(members)
    }

    fn get(&self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|v| !v.is_null())
    }

    pub fn is_present(&self, name: &str) -> bool {
        self.get(name).is_some()
    }

    /// Fails with `MissingParameter` for the first listed name that is absent.
    pub fn require(&self, names: &[&str]) -> Result<()> {
        match names.iter().find(|n| !self.is_present(n)) {
            Some(name) => Err(Error::new(Code::MissingParameter, format!("{name} is required"))),
            None => Ok(()),
        }
    }

    pub fn string(&self, name: &str) -> Result<Option<&'a str>> {
        self.get(name)
            .map(|v| v.as_str().ok_or_else(|| invalid(name, "must be a string")))
            .transpose()
    }

    pub fn boolean(&self, name: &str) -> Result<Option<bool>> {
        self.get(name)
            .map(|v| v.as_bool().ok_or_else(|| invalid(name, "must be a boolean")))
            .transpose()
    }

    pub fn integer(&self, name: &str, range: RangeInclusive<u32>) -> Result<Option<u32>> {
        self.get(name)
            .map(|v| {
                let n = match v {
                    Value::Number(n) if !n.is_f64() => n.as_i64(),
                    _ => None,
                };
                n.and_then(|n| u32::try_from(n).ok())
                    .filter(|n| range.contains(n))
                    .ok_or_else(|| {
                        invalid(
                            name,
                            format!(
                                "must be an integer from {} to {}",
                                range.start(),
                                range.end()
                            ),
                        )
                    })
            })
            .transpose()
    }

    pub fn object(&self, name: &str) -> Result<Option<&'a Map<String, Value>>> {
        self.get(name)
            .map(|v| v.as_object().ok_or_else(|| invalid(name, "must be an object")))
            .transpose()
    }

    /// A group or deduplication id: 1 to 128 characters of `A-Z a-z 0-9 _ -`.
    pub fn identifier(&self, name: &str) -> Result<Option<&'a str>> {
        match self.string(name)? {
            Some(s) if !(1..=128).contains(&s.len()) || !s.bytes().all(is_name_byte) => {
                Err(invalid(name, "must be 1 to 128 characters of A-Z a-z 0-9 _ -"))
            }
            other => Ok(other),
        }
    }
}

pub fn is_name_byte(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_' || b == b'-'
}

pub fn invalid(name: &str, why: impl std::fmt::Display) -> Error {
    Error::new(Code::InvalidParameterValue, format!("{name} {why}"))
}
EOF
cat > src/lib.rs <<'EOF'
pub mod error;
pub mod params;
EOF
echo 'fn main() {}' > src/main.rs
cargo build 2>&1 | tail -5; cat .gitignore

