    pub fn expire(&mut self, now: u64) {
        let retention = u64::from(self.settings.retention_seconds);
        while let Some(&(sent_at, arrival)) = self.by_age.first() {
            if now < sent_at + retention {
                break;
            }
            self.remove(arrival);
        }
    }

    pub fn len(&self) -> usize {
        self.messages.len()
    }

    pub fn is_empty(&self) -> bool {
        self.messages.is_empty()
    }

    pub fn counts(&self, now: u64) -> Counts {
        let mut counts = Counts::default();
        for message in self.messages.values() {
            match message.state(now) {
                State::Visible => counts.visible += 1,
                State::InFlight => counts.in_flight += 1,
                State::Delayed => counts.delayed += 1,
            }
        }
        counts
    }

    /// The earlier acceptance of `dedup_id`, if it is still inside the window.
    pub fn duplicate_of(&self, dedup_id: &str, now: u64) -> Option<Accepted> {
        match self.dedup.get(dedup_id) {
            Some(&(at, accepted)) if now - at < DEDUP_WINDOW => Some(accepted),
            _ => None,
        }
    }

    /// Records a FIFO send's deduplication id; the message must be `add`ed
    /// right after so the recorded sequence number is the one it gets.
    pub fn remember_dedup(&mut self, dedup_id: &str, message_id: u64, now: u64) {
        let accepted = Accepted { message_id, sequence: self.next_sequence };
        self.dedup.insert(dedup_id.to_owned(), (now, accepted));
    }

    /// Appends a message and returns its sequence number on a FIFO queue.
    pub fn add(&mut self, mut message: Message, now: u64) -> Option<u64> {
        if self.settings.fifo {
            message.sequence = Some(self.next_sequence);
            self.next_sequence += 1;
        }
        let sequence = message.sequence;
        self.by_age.insert((message.sent_at, self.next_arrival));
        self.messages.insert(self.next_arrival, message);
        self.next_arrival += 1;
        self.expire(now);
        sequence
    }

    /// Accepts a message moved here from another queue's dead-letter rule.
    pub fn add_dead_letter(&mut self, mut message: Message, now: u64) {
        message.reset_for_dead_letter();
        self.add(message, now);
    }

    fn remove(&mut self, arrival: u64) -> Option<Message> {
        let message = self.messages.remove(&arrival)?;
        self.by_age.remove(&(message.sent_at, arrival));
        Some(message)
    }

    pub fn purge(&mut self) {
        self.messages.clear();
        self.by_age.clear();
    }

    /// Delivers up to `max` messages. Returns them with their new receipt
    /// handles, and the messages that must move to the dead-letter queue.
    pub fn receive(
        &mut self,
        now: u64,
        max: usize,
        visibility_timeout: u32,
        next_handle: &mut u64,
    ) -> (Vec<(u64, Message)>, Vec<Message>) {
        let dead_letter_after = self.settings.dead_letter.as_ref().map(|d| d.max_receive_count);
        let until = now + u64::from(visibility_timeout);
        let mut delivered = Vec::new();
        let mut dead_keys = Vec::new();
        // Groups that already have an earlier message in the queue.
        let mut seen_groups: HashSet<Rc<str>> = HashSet::new();

        for (&arrival, message) in self.messages.iter_mut() {
            if delivered.len() == max {
                break;
            }
            if let Some(group) = &message.group {
                if !seen_groups.insert(Rc::clone(group)) {
                    continue;
                }
            }
            if message.state(now) != State::Visible {
                continue;
            }
            if dead_letter_after.is_some_and(|limit| message.receive_count >= limit) {
                // The message leaves the queue, so it does not block its group.
                if let Some(group) = &message.group {
                    seen_groups.remove(group);
                }
                dead_keys.push(arrival);
                continue;
            }
            let handle = *next_handle;
            *next_handle += 1;
            message.receive_count += 1;
            message.first_received_at.get_or_insert(now);
            message.hold = Hold::InFlight { handle, until };
            self.handles.insert(handle, arrival);
            delivered.push((handle, message.clone()));
        }

        let dead = dead_keys.into_iter().filter_map(|k| self.remove(k)).collect();
        (delivered, dead)
    }

    /// The arrival number of the message `handle` is the latest handle of,
    /// provided that message is in flight.
    pub fn in_flight(&self, handle: u64, now: u64) -> Option<u64> {
        let arrival = *self.handles.get(&handle)?;
        let message = self.messages.get(&arrival)?;
        match message.hold {
            Hold::InFlight { handle: latest, .. }
                if latest == handle && message.state(now) == State::InFlight =>
            {
                Some(arrival)
            }
            _ => None,
        }
    }

    pub fn delete(&mut self, arrival: u64) {
        self.remove(arrival);
    }

    /// Ends the visibility timeout of an in-flight message at `until`.
    pub fn set_in_flight_until(&mut self, arrival: u64, until: u64) {
        if let Some(Message { hold: Hold::InFlight { until: end, .. }, .. }) =
            self.messages.get_mut(&arrival)
        {
            *end = until;
        }
    }
}

