                // The message leaves the queue, so it does not block its group.
                if let Some(group) = &message.group {
                    seen_groups.remove(group);
                }
                dead_keys.push(arrival);
                continue;
            }
            let handle = *next_handle;
            *next_handle += 1;
            message.receive_count += 1;
            message.first_received_at.get_or_insert(now);
            message.hold = Hold::InFlight { handle, until };
            self.handles.insert(handle, arrival);
            delivered.push((handle, message.clone()));
        }

        let dead = dead_keys.into_iter().filter_map(|k| self.remove(k)).collect();
