//! The command layer: parses one request line, runs it against the queues
//! and builds the response.

use crate::error::{Code, Error, Result};
use crate::params::{invalid, Params};
use crate::queue::{
    is_valid_queue_name, DeadLetter, Message, Queue, Settings, MAX_MESSAGES,
};
use serde_json::{json, Map, Value};
use std::collections::HashMap;
use std::rc::Rc;

const MAX_QUEUES: usize = 1000;
const MAX_BODY_BYTES: usize = 1024;
const FIFO_SUFFIX: &str = ".fifo";

/// Attributes named in a `CreateQueue` or `SetQueueAttributes` request.
#[derive(Default)]
struct AttributeUpdate {
    visibility_timeout: Option<u32>,
    delay_seconds: Option<u32>,
    retention_seconds: Option<u32>,
    fifo: Option<bool>,
    content_based_dedup: Option<bool>,
    dead_letter_queue: Option<String>,
    max_receive_count: Option<u32>,
}

impl AttributeUpdate {
    fn parse(params: &Params) -> Result<Self> {
        let Some(members) = params.object("Attributes")? else {
            return Ok(Self::default());
        };
        const KNOWN: [&str; 7] = [
            "VisibilityTimeout",
            "DelaySeconds",
            "RetentionSeconds",
            "Fifo",
            "ContentBasedDeduplication",
            "DeadLetterQueue",
            "MaxReceiveCount",
        ];
        if let Some(name) = members
            .iter()
            .find(|(name, value)| !value.is_null() && !KNOWN.contains(&name.as_str()))
            .map(|(name, _)| name)
        {
            return Err(invalid("Attributes", format!("has unknown attribute {name}")));
        }
        let attrs = Params::new(members);
        Ok(AttributeUpdate {
            visibility_timeout: attrs.integer("VisibilityTimeout", 0..=43_200)?,
            delay_seconds: attrs.integer("DelaySeconds", 0..=900)?,
            retention_seconds: attrs.integer("RetentionSeconds", 60..=1_209_600)?,
            fifo: attrs.boolean("Fifo")?,
            content_based_dedup: attrs.boolean("ContentBasedDeduplication")?,
            dead_letter_queue: attrs.string("DeadLetterQueue")?.map(str::to_owned),
            max_receive_count: attrs.integer("MaxReceiveCount", 1..=1000)?,
        })
    }

    /// Both dead-letter attributes or neither.
    fn check_dead_letter_pair(&self) -> Result<()> {
        if self.dead_letter_queue.is_some() != self.max_receive_count.is_some() {
            return Err(invalid(
                "Attributes",
                "must set DeadLetterQueue and MaxReceiveCount together",
            ));
        }
        Ok(())
    }

    fn dead_letter(&self) -> Option<DeadLetter> {
        Some(DeadLetter {
            queue: self.dead_letter_queue.clone()?,
            max_receive_count: self.max_receive_count?,
        })
    }

    /// The settings of a new queue: the given attributes over the defaults.
    fn into_settings(self) -> Settings {
        let defaults = Settings::default();
        Settings {
            visibility_timeout: self.visibility_timeout.unwrap_or(defaults.visibility_timeout),
            delay_seconds: self.delay_seconds.unwrap_or(defaults.delay_seconds),
            retention_seconds: self.retention_seconds.unwrap_or(defaults.retention_seconds),
            fifo: self.fifo.unwrap_or(defaults.fifo),
            content_based_dedup: self.content_based_dedup.unwrap_or(defaults.content_based_dedup),
            dead_letter: self.dead_letter(),
        }
    }
}

#[derive(Default)]
pub struct Service {
    queues: HashMap<String, Queue>,
    now: u64,
    messages_accepted: u64,
    handles_issued: u64,
}

impl Service {
    pub fn new() -> Self {
        Self::default()
    }

    /// Runs one input line and returns its response line (without `\n`).
    pub fn handle_line(&mut self, line: &[u8]) -> String {
        let response = match self.run(line) {
            Ok(mut result) => {
                result.insert("ok".into(), Value::Bool(true));
                Value::Object(result)
            }
            Err(e) => json!({
                "ok": false,
                "error": { "code": e.code.as_str(), "message": e.message },
            }),
        };
        response.to_string()
    }

    fn run(&mut self, line: &[u8]) -> Result<Map<String, Value>> {
        let request_error = |why: &str| Error::new(Code::InvalidRequest, why);
        let text = std::str::from_utf8(line).map_err(|_| request_error("line is not UTF-8"))?;
        let Ok(Value::Object(members)) = serde_json::from_str::<Value>(text) else {
            return Err(request_error("line is not a JSON object"));
        };
        let command = members
            .get("Command")
            .and_then(Value::as_str)
            .ok_or_else(|| request_error("Command must be a string"))?;
        let params = Params::new(&members);
        let result = match command {
            "CreateQueue" => self.create_queue(&params),
            "SetQueueAttributes" => self.set_queue_attributes(&params),
            "GetQueueAttributes" => self.get_queue_attributes(&params),
            "ListQueues" => self.list_queues(&params),
            "DeleteQueue" => self.delete_queue(&params),
            "PurgeQueue" => self.purge_queue(&params),
            "Tick" => self.tick(&params),
            "SendMessage" => self.send_message(&params),
            "ReceiveMessage" => self.receive_message(&params),
            "DeleteMessage" => self.change_handle(&params, None),
            "ChangeMessageVisibility" => self.change_handle(&params, Some(())),
            _ => return Err(request_error("unknown command")),
        }?;
        Ok(match result {
            Value::Object(map) => map,
            _ => Map::new(),
        })
    }

    /// Finds a queue and applies retention, so callers see only live messages.
    fn queue(&mut self, name: &str) -> Result<&mut Queue> {
        lookup(&mut self.queues, name, self.now)
    }

    fn create_queue(&mut self, params: &Params) -> Result<Value> {
        params.require(&["QueueName"])?;
        let name = params
            .string("QueueName")?
            .ok_or_else(|| invalid("QueueName", "must be a string"))?;
        if !is_valid_queue_name(name) {
            return Err(Error::new(Code::QueueNameInvalid, "queue name breaks the naming rules"));
        }
        let attrs = AttributeUpdate::parse(params)?;
        let settings = attrs_checked(attrs, Some(name))?;
        if let Some(existing) = self.queues.get(name) {
            return if existing.settings == settings {
                Ok(json!({}))
            } else {
                Err(Error::new(Code::QueueAlreadyExists, "queue exists with other attributes"))
            };
        }
        if let Some(dead_letter) = &settings.dead_letter {
            let target = self.queues.get(&dead_letter.queue).ok_or_else(missing_dead_letter)?;
            if target.settings.fifo != settings.fifo {
                return Err(invalid("DeadLetterQueue", "must be of the same type as the queue"));
            }
        }
        if self.queues.len() >= MAX_QUEUES {
            return Err(Error::new(Code::LimitExceeded, "too many queues"));
        }
        self.queues.insert(name.to_owned(), Queue::new(settings));
        Ok(json!({}))
    }

    fn set_queue_attributes(&mut self, params: &Params) -> Result<Value> {
        params.require(&["QueueName", "Attributes"])?;
        let name = required_name(params)?;
        let attrs = AttributeUpdate::parse(params)?;
        let now = self.now;
        let fifo = lookup(&mut self.queues, name, now)?.settings.fifo;
        if attrs.fifo.is_some() {
            return Err(Error::new(Code::UnsupportedOperation, "the type of a queue cannot change"));
        }
        if attrs.content_based_dedup == Some(true) && !fifo {
            return Err(invalid("ContentBasedDeduplication", "needs a FIFO queue"));
        }
        attrs.check_dead_letter_pair()?;
        if let Some(target_name) = &attrs.dead_letter_queue {
            let target = self.queues.get(target_name).ok_or_else(missing_dead_letter)?;
            if target_name == name || target.settings.fifo != fifo {
                return Err(invalid(
                    "DeadLetterQueue",
                    "must be another queue of the same type",
                ));
            }
        }
        let dead_letter = attrs.dead_letter();
        let queue = self.queue(name)?;
        let s = &mut queue.settings;
        s.visibility_timeout = attrs.visibility_timeout.unwrap_or(s.visibility_timeout);
        s.delay_seconds = attrs.delay_seconds.unwrap_or(s.delay_seconds);
        s.retention_seconds = attrs.retention_seconds.unwrap_or(s.retention_seconds);
        s.content_based_dedup = attrs.content_based_dedup.unwrap_or(s.content_based_dedup);
        if dead_letter.is_some() {
            s.dead_letter = dead_letter;
        }
        queue.expire(now);
        Ok(json!({}))
    }

    fn get_queue_attributes(&mut self, params: &Params) -> Result<Value> {
        params.require(&["QueueName"])?;
        let name = required_name(params)?;
        let now = self.now;
        let queue = self.queue(name)?;
        let s = &queue.settings;
        let mut attributes = json!({
            "VisibilityTimeout": s.visibility_timeout,
            "DelaySeconds": s.delay_seconds,
            "RetentionSeconds": s.retention_seconds,
            "Fifo": s.fifo,
            "ContentBasedDeduplication": s.content_based_dedup,
        });
        if let Some(d) = &s.dead_letter {
            attributes["DeadLetterQueue"] = json!(d.queue);
            attributes["MaxReceiveCount"] = json!(d.max_receive_count);
        }
        let counts = queue.counts(now);
        Ok(json!({
            "Attributes": attributes,
            "Counts": {
                "Visible": counts.visible,
                "InFlight": counts.in_flight,
                "Delayed": counts.delayed,
            },
        }))
    }

    fn list_queues(&mut self, params: &Params) -> Result<Value> {
        let prefix = params.string("Prefix")?.unwrap_or("");
        let mut names: Vec<&str> =
            self.queues.keys().map(String::as_str).filter(|n| n.starts_with(prefix)).collect();
        names.sort_unstable();
        Ok(json!({ "QueueNames": names }))
    }

    fn delete_queue(&mut self, params: &Params) -> Result<Value> {
        params.require(&["QueueName"])?;
