        let delay = delay.unwrap_or(queue.settings.delay_seconds);
        if let Some(key) = dedup_key {
            queue.remember_dedup(key, id, now);
        }
        let message = Message::new(id, body.to_owned(), now, delay, group.map(Rc::from));
        let sequence = queue.add(message, now);
        let mut result = json!({ "MessageId": format_id('m', id) });
        if let Some(sequence) = sequence {
            result["SequenceNumber"] = json!(sequence);
        }
        Ok(result)
    }

    fn receive_message(&mut self, params: &Params) -> Result<Value> {
        params.require(&["QueueName"])?;
        let name = required_name(params)?;
        let max = params.integer("MaxMessages", 1..=10)?.unwrap_or(1);
        let visibility = params.integer("VisibilityTimeout", 0..=43_200)?;

        let now = self.now;
        let queue = lookup(&mut self.queues, name, now)?;
        let visibility = visibility.unwrap_or(queue.settings.visibility_timeout);
        let dead_letter = queue.settings.dead_letter.clone();
        let mut next_handle = self.handles_issued + 1;
        let (delivered, dead) = queue.receive(now, max as usize, visibility, &mut next_handle);
        self.handles_issued = next_handle - 1;

        if let Some(dead_letter) = dead_letter.filter(|_| !dead.is_empty()) {
            let target = self
                .queues
                .get_mut(&dead_letter.queue)
                .expect("a configured dead-letter queue exists until it is deleted");
            target.expire(now);
            for message in dead {
                target.add_dead_letter(message, now);
            }
        }

        let messages: Vec<Value> = delivered
            .into_iter()
            .map(|(handle, m)| {
                let mut v = json!({
                    "MessageId": format_id('m', m.id),
                    "ReceiptHandle": format_id('r', handle),
                    "Body": m.body,
                    "ReceiveCount": m.receive_count,
                    "SentAt": m.sent_at,
                    "FirstReceivedAt": m.first_received_at,
                });
                if let (Some(group), Some(sequence)) = (&m.group, m.sequence) {
                    v["GroupId"] = json!(&**group);
                    v["SequenceNumber"] = json!(sequence);
                }
                v
            })
            .collect();
        Ok(json!({ "Messages": messages }))
    }

    /// `DeleteMessage` (`new_visibility == None`) and `ChangeMessageVisibility`.
    fn change_handle(&mut self, params: &Params, new_visibility: Option<()>) -> Result<Value> {
        let change = new_visibility.is_some();
        let required: &[&str] = if change {
            &["QueueName", "ReceiptHandle", "VisibilityTimeout"]
        } else {
            &["QueueName", "ReceiptHandle"]
        };
        params.require(required)?;
        let name = required_name(params)?;
        let handle_text = params.string("ReceiptHandle")?.unwrap_or_default();
        let timeout = params.integer("VisibilityTimeout", 0..=43_200)?;

        let now = self.now;
        let issued = self.handles_issued;
        let queue = lookup(&mut self.queues, name, now)?;
        let handle = parse_handle(handle_text, issued)
            .ok_or_else(|| Error::new(Code::ReceiptHandleInvalid, "handle was never issued"))?;
        let arrival = queue
            .in_flight(handle, now)
            .ok_or_else(|| Error::new(Code::ReceiptHandleExpired, "handle is no longer usable"))?;
        match timeout.filter(|_| change) {
            Some(t) => queue.set_in_flight_until(arrival, now + u64::from(t)),
            None => queue.delete(arrival),
        }
        Ok(json!({}))
    }
}

/// Checks the cross-attribute rules of `CreateQueue` that precede the lookup
/// of an existing queue, and returns the settings the request describes.
fn attrs_checked(attrs: AttributeUpdate, name: Option<&str>) -> Result<Settings> {
    let fifo = attrs.fifo.unwrap_or(false);
    if name.is_some_and(|n| n.ends_with(FIFO_SUFFIX)) != fifo {
        return Err(Error::new(
            Code::QueueNameInvalid,
            "a name ending in .fifo and Fifo must go together",
        ));
    }
    if attrs.content_based_dedup == Some(true) && !fifo {
        return Err(invalid("ContentBasedDeduplication", "needs a FIFO queue"));
    }
    attrs.check_dead_letter_pair()?;
    Ok(attrs.into_settings())
}

fn lookup<'a>(queues: &'a mut HashMap<String, Queue>, name: &str, now: u64) -> Result<&'a mut Queue> {
    let queue = queues
        .get_mut(name)
        .ok_or_else(|| Error::new(Code::QueueDoesNotExist, format!("no queue named {name}")))?;
    queue.expire(now);
    Ok(queue)
}

fn required_name<'a>(params: &Params<'a>) -> Result<&'a str> {
    params.string("QueueName")?.ok_or_else(|| invalid("QueueName", "must be a string"))
}

fn missing_dead_letter() -> Error {
    Error::new(Code::QueueDoesNotExist, "the dead-letter queue does not exist")
}

fn format_id(prefix: char, n: u64) -> String {
    format!("{prefix}-{n}")
}

/// Parses `r-<n>` exactly as issued: no sign, no leading zeros, `1 <= n <= issued`.
fn parse_handle(text: &str, issued: u64) -> Option<u64> {
    let digits = text.strip_prefix("r-")?;
    if digits.starts_with('0') || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    digits.parse().ok().filter(|n| (1..=issued).contains(n))
}

