            return if existing.settings == settings {
                Ok(json!({}))
            } else {
                Err(Error::new(Code::QueueAlreadyExists, "queue exists with other attributes"))
            };
        }
        if let Some(dead_letter) = &settings.dead_letter {
            let target = self.queues.get(&dead_letter.queue).ok_or_else(missing_dead_letter)?;
            if target.settings.fifo != settings.fifo {
                return Err(invalid("DeadLetterQueue", "must be of the same type as the queue"));
            }
        }
        if self.queues.len() >= MAX_QUEUES {
            return Err(Error::new(Code::LimitExceeded, "too many queues"));
        }
        self.queues.insert(name.to_owned(), Queue::new(settings));
        Ok(json!({}))
    }

    fn set_queue_attributes(&mut self, params: &Params) -> Result<Value> {
        params.require(&["QueueName", "Attributes"])?;
        let name = required_name(params)?;
        let attrs = AttributeUpdate::parse(params)?;
        let now = self.now;
        let fifo = lookup(&mut self.queues, name, now)?.settings.fifo;
        if attrs.fifo.is_some() {
            return Err(Error::new(Code::UnsupportedOperation, "the type of a queue cannot change"));
        }
        if attrs.content_based_dedup == Some(true) && !fifo {
            return Err(invalid("ContentBasedDeduplication", "needs a FIFO queue"));
        }
        attrs.check_dead_letter_pair()?;
        if let Some(target_name) = &attrs.dead_letter_queue {
            let target = self.queues.get(target_name).ok_or_else(missing_dead_letter)?;
            if target_name == name || target.settings.fifo != fifo {
                return Err(invalid(
                    "DeadLetterQueue",
                    "must be another queue of the same type",
                ));
            }
        }
        let dead_letter = attrs.dead_letter();
        let queue = self.queue(name)?;
        let s = &mut queue.settings;
        s.visibility_timeout = attrs.visibility_timeout.unwrap_or(s.visibility_timeout);
        s.delay_seconds = attrs.delay_seconds.unwrap_or(s.delay_seconds);
        s.retention_seconds = attrs.retention_seconds.unwrap_or(s.retention_seconds);
        s.content_based_dedup = attrs.content_based_dedup.unwrap_or(s.content_based_dedup);
        if dead_letter.is_some() {
            s.dead_letter = dead_letter;
        }
        queue.expire(now);
        Ok(json!({}))
    }

    fn get_queue_attributes(&mut self, params: &Params) -> Result<Value> {
        params.require(&["QueueName"])?;
        let name = required_name(params)?;
        let now = self.now;
        let queue = self.queue(name)?;
        let s = &queue.settings;
        let mut attributes = json!({
            "VisibilityTimeout": s.visibility_timeout,
            "DelaySeconds": s.delay_seconds,
            "RetentionSeconds": s.retention_seconds,
            "Fifo": s.fifo,
            "ContentBasedDeduplication": s.content_based_dedup,
        });
        if let Some(d) = &s.dead_letter {
            attributes["DeadLetterQueue"] = json!(d.queue);
            attributes["MaxReceiveCount"] = json!(d.max_receive_count);
        }
        let counts = queue.counts(now);
        Ok(json!({
            "Attributes": attributes,
            "Counts": {
                "Visible": counts.visible,
                "InFlight": counts.in_flight,
                "Delayed": counts.delayed,
            },
        }))
    }

    fn list_queues(&mut self, params: &Params) -> Result<Value> {
        let prefix = params.string("Prefix")?.unwrap_or("");
        let mut names: Vec<&str> =
            self.queues.keys().map(String::as_str).filter(|n| n.starts_with(prefix)).collect();
        names.sort_unstable();
        Ok(json!({ "QueueNames": names }))
    }

    fn delete_queue(&mut self, params: &Params) -> Result<Value> {
        params.require(&["QueueName"])?;
        let name = required_name(params)?;
        self.queue(name)?;
        self.queues.remove(name);
        for queue in self.queues.values_mut() {
            if queue.settings.dead_letter.as_ref().is_some_and(|d| d.queue == name) {
                queue.settings.dead_letter = None;
            }
        }
        Ok(json!({}))
    }

    fn purge_queue(&mut self, params: &Params) -> Result<Value> {
        params.require(&["QueueName"])?;
        let name = required_name(params)?;
        self.queue(name)?.purge();
        Ok(json!({}))
    }

    fn tick(&mut self, params: &Params) -> Result<Value> {
        params.require(&["Seconds"])?;
        let seconds = params.integer("Seconds", 0..=1_209_600)?.unwrap_or(0);
        self.now += u64::from(seconds);
        Ok(json!({ "Now": self.now }))
    }

    fn send_message(&mut self, params: &Params) -> Result<Value> {
        params.require(&["QueueName", "Body"])?;
        let name = required_name(params)?;
        let body = params.string("Body")?.unwrap_or_default();
        if body.is_empty() || body.len() > MAX_BODY_BYTES {
            return Err(invalid("Body", "must be 1 to 1024 bytes"));
        }
