        let group = params.identifier("GroupId")?;
        let dedup_id = params.identifier("DeduplicationId")?;

        let now = self.now;
        let queue = lookup(&mut self.queues, name, now)?;
        let fifo = queue.settings.fifo;
        if (!fifo && (group.is_some() || dedup_id.is_some())) || (fifo && delay.is_some()) {
            return Err(Error::new(
                Code::UnsupportedOperation,
                "GroupId and DeduplicationId are for FIFO queues, DelaySeconds for standard ones",
            ));
        }
