        if fifo {
            if group.is_none() {
                return Err(Error::new(Code::MissingParameter, "GroupId is required"));
            }
            if dedup_id.is_none() && !queue.settings.content_based_dedup {
                return Err(Error::new(Code::MissingParameter, "DeduplicationId is required"));
            }
            let key = dedup_id.unwrap_or(body);
            if let Some(original) = queue.duplicate_of(key, now) {
                return Ok(json!({
                    "MessageId": format_id('m', original.message_id),
