/// of an existing queue, and returns the settings the request describes.
fn attrs_checked(attrs: AttributeUpdate, name: Option<&str>) -> Result<Settings> {
    let fifo = attrs.fifo.unwrap_or(false);
    if name.is_some_and(|n| n.ends_with(FIFO_SUFFIX)) != fifo {
        return Err(Error::new(
            Code::QueueNameInvalid,
            "a name ending in .fifo and Fifo must go together",
        ));
    }
