    Ok(attrs.into_settings())
}

fn lookup<'a>(queues: &'a mut HashMap<String, Queue>, name: &str, now: u64) -> Result<&'a mut Queue> {
    let queue = queues
        .get_mut(name)
        .ok_or_else(|| Error::new(Code::QueueDoesNotExist, format!("no queue named {name}")))?;
    queue.expire(now);
    Ok(queue)
}

fn required_name<'a>(params: &Params<'a>) -> Result<&'a str> {
    params.string("QueueName")?.ok_or_else(|| invalid("QueueName", "must be a string"))
}

fn missing_dead_letter() -> Error {
    Error::new(Code::QueueDoesNotExist, "the dead-letter queue does not exist")
}

fn format_id(prefix: char, n: u64) -> String {
    format!("{prefix}-{n}")
}

/// Parses `r-<n>` exactly as issued: no sign, no leading zeros, `1 <= n <= issued`.
fn parse_handle(text: &str, issued: u64) -> Option<u64> {
    let digits = text.strip_prefix("r-")?;
    if digits.starts_with('0') || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    digits.parse().ok().filter(|n| (1..=issued).contains(n))
}

