use miniq::Service;
use serde_json::{json, Value};

fn run(lines: &[&str]) -> Vec<Value> {
    let mut service = Service::new();
    lines
        .iter()
        .map(|l| serde_json::from_str(&service.handle_line(l.as_bytes())).unwrap())
        .collect()
