    assert!(out.iter().all(|v| code(v) == "InvalidRequest"));
}

#[test]
fn standard_send_receive_delete() {
    let out = run(&[
        r#"{"Command":"CreateQueue","QueueName":"jobs"}"#,
        r#"{"Command":"SendMessage","QueueName":"jobs","Body":"a"}"#,
        r#"{"Command":"ReceiveMessage","QueueName":"jobs"}"#,
        r#"{"Command":"DeleteMessage","QueueName":"jobs","ReceiptHandle":"r-1"}"#,
        r#"{"Command":"DeleteMessage","QueueName":"jobs","ReceiptHandle":"r-1"}"#,
        r#"{"Command":"DeleteMessage","QueueName":"jobs","ReceiptHandle":"r-01"}"#,
    ]);
    assert_eq!(out[1], json!({"ok": true, "MessageId": "m-1"}));
    assert_eq!(
        out[2]["Messages"][0],
        json!({"MessageId":"m-1","ReceiptHandle":"r-1","Body":"a","ReceiveCount":1,
