        .map(|l| serde_json::from_str(&service.handle_line(l.as_bytes())).unwrap())
        .collect()
}

fn code(v: &Value) -> &str {
    assert_eq!(v["ok"], false, "{v}");
    v["error"]["code"].as_str().unwrap()
}

#[test]
fn bad_lines_are_invalid_requests() {
    let out = run(&["", "[]", "{\"Command\": 1}", "{\"Command\": \"Nope\"}", "{} x"]);
    assert!(out.iter().all(|v| code(v) == "InvalidRequest"));
}

#[test]
fn standard_send_receive_delete() {
    let out = run(&[
        r#"{"Command":"CreateQueue","QueueName":"jobs"}"#,
        r#"{"Command":"SendMessage","QueueName":"jobs","Body":"a"}"#,
        r#"{"Command":"ReceiveMessage","QueueName":"jobs"}"#,
        r#"{"Command":"DeleteMessage","QueueName":"jobs","ReceiptHandle":"r-1"}"#,
        r#"{"Command":"DeleteMessage","QueueName":"jobs","ReceiptHandle":"r-1"}"#,
        r#"{"Command":"DeleteMessage","QueueName":"jobs","ReceiptHandle":"r-01"}"#,
    ]);
    assert_eq!(out[1], json!({"ok": true, "MessageId": "m-1"}));
    assert_eq!(
        out[2]["Messages"][0],
        json!({"MessageId":"m-1","ReceiptHandle":"r-1","Body":"a","ReceiveCount":1,
               "SentAt":0,"FirstReceivedAt":0})
    );
    assert_eq!(out[3], json!({"ok": true}));
    assert_eq!(code(&out[4]), "ReceiptHandleExpired");
    assert_eq!(code(&out[5]), "ReceiptHandleInvalid");
}

#[test]
fn visibility_timeout_ends_with_tick() {
