#[test]
fn fifo_deduplicates_and_orders_by_group() {
    let out = run(&[
        r#"{"Command":"CreateQueue","QueueName":"q.fifo","Attributes":{"Fifo":true}}"#,
        r#"{"Command":"SendMessage","QueueName":"q.fifo","Body":"a","GroupId":"g","DeduplicationId":"d"}"#,
        r#"{"Command":"SendMessage","QueueName":"q.fifo","Body":"b","GroupId":"g","DeduplicationId":"d"}"#,
        r#"{"Command":"Tick","Seconds":300}"#,
        r#"{"Command":"SendMessage","QueueName":"q.fifo","Body":"c","GroupId":"g","DeduplicationId":"d"}"#,
        r#"{"Command":"ReceiveMessage","QueueName":"q.fifo","MaxMessages":10}"#,
        r#"{"Command":"SendMessage","QueueName":"q.fifo","Body":"c","DeduplicationId":"e"}"#,
    ]);
    assert_eq!(out[2], json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(out[4]["SequenceNumber"], 2);
    let received = out[5]["Messages"].as_array().unwrap();
    assert_eq!(received.len(), 1, "one message per group");
    assert_eq!(received[0]["Body"], "a");
    assert_eq!(code(&out[6]), "MissingParameter");
}

