#[test]
fn retention_removes_messages_and_create_is_idempotent() {
    let out = run(&[
        r#"{"Command":"CreateQueue","QueueName":"q","Attributes":{"RetentionSeconds":60}}"#,
        r#"{"Command":"CreateQueue","QueueName":"q","Attributes":{"RetentionSeconds":60}}"#,
        r#"{"Command":"CreateQueue","QueueName":"q"}"#,
        r#"{"Command":"SendMessage","QueueName":"q","Body":"a","DelaySeconds":5}"#,
        r#"{"Command":"GetQueueAttributes","QueueName":"q"}"#,
        r#"{"Command":"Tick","Seconds":60}"#,
        r#"{"Command":"GetQueueAttributes","QueueName":"q"}"#,
    ]);
    assert_eq!(out[1], json!({"ok": true}));
    assert_eq!(code(&out[2]), "QueueAlreadyExists");
    assert_eq!(out[4]["Counts"], json!({"Visible": 0, "InFlight": 0, "Delayed": 1}));
    assert_eq!(out[6]["Counts"], json!({"Visible": 0, "InFlight": 0, "Delayed": 0}));
}

