#[test]
fn queue_fills_to_limit_quickly() {
    let mut service = Service::new();
    service.handle_line(br#"{"Command":"CreateQueue","QueueName":"q"}"#);
    for _ in 0..100_000 {
        let r = service.handle_line(br#"{"Command":"SendMessage","QueueName":"q","Body":"x"}"#);
        assert!(r.contains("true"));
    }
    let r = service.handle_line(br#"{"Command":"SendMessage","QueueName":"q","Body":"x"}"#);
    assert!(r.contains("LimitExceeded"));
}
